<script setup lang="ts">
import {computed,onUnmounted,ref,watch} from 'vue'
import {api,displayText,ruleVersionText,label,time,type Run} from '../api'
import {matchesAssessment} from '../assessmentSelection'
import type {AssessmentReport,EvidenceSnapshot} from '../evidence'
import {useExecution,executionStatuses} from '../execution'
import Icon from './Icon.vue'
const props=defineProps<{snapshot:EvidenceSnapshot|null;run:Run|null;runs:Run[]}>()
const emit=defineEmits<{'open-run':[run:Run];'return-workbench':[];'open-task':[id:string];'run-updated':[run:Run]}>()
const report=ref<AssessmentReport|null>(null),loading=ref(false),error=ref(''),recordId=ref(''),execution=useExecution()
const resolvedRun=ref<Run|null>(null)
const effectiveRun=computed(()=>resolvedRun.value?.id===props.run?.id?resolvedRun.value:props.run)
const validRun=computed(()=>props.snapshot?matchesAssessment(props.snapshot,effectiveRun.value)?effectiveRun.value:null:effectiveRun.value?.result?.report_id||['queued','running'].includes(effectiveRun.value?.status||'')?effectiveRun.value:null)
const legacyRun=computed(()=>!props.snapshot&&effectiveRun.value?.result&&!effectiveRun.value.result.report_id?effectiveRun.value:null)
const savedRuns=computed(()=>props.runs.filter(run=>run.status==='completed'))
const linked=computed(()=>execution.tasks.value.filter(task=>task.source_run_id===validRun.value?.id))
let generation=0,timer:ReturnType<typeof setTimeout>|undefined
async function load(){const token=++generation;clearTimeout(timer);report.value=null;error.value='';const original=props.run;if(!original){loading.value=false;return}loading.value=true;try{const run=await api<Run>(`/runs/${encodeURIComponent(original.id)}`);if(token!==generation)return;if(run.incident_id!==original.incident_id||run.evidence_snapshot_id!==original.evidence_snapshot_id||(props.snapshot&&!matchesAssessment(props.snapshot,run)))throw new Error('核查运行与当前事件上下文不一致。');resolvedRun.value=run;emit('run-updated',run);if(run.status!=='completed'||(!props.snapshot&&!run.result?.report_id))return;const value=await api<AssessmentReport>(`/runs/${encodeURIComponent(run.id)}/assessment-report`);if(token!==generation)return;if(value.run_id!==run.id||value.incident_id!==run.incident_id||value.evidence_snapshot_id!==run.evidence_snapshot_id)throw new Error('报告关联与当前核查不一致，已停止显示。');report.value=value}catch(e){if(token===generation)error.value=(e as Error).message}finally{if(token===generation){loading.value=false;if(['queued','running'].includes(effectiveRun.value?.status||''))timer=setTimeout(load,1200)}}}
function chooseRun(){const run=props.runs.find(item=>item.id===recordId.value);if(run)emit('open-run',run)}
function download(){if(!report.value)return;const url=URL.createObjectURL(new Blob([JSON.stringify(report.value,null,2)],{type:'application/json;charset=utf-8'}));const anchor=document.createElement('a');anchor.href=url;anchor.download=`天亨-规则研判报告-${report.value.id}.json`;anchor.click();URL.revokeObjectURL(url)}
function downloadLegacy(){if(!legacyRun.value)return;const url=URL.createObjectURL(new Blob([JSON.stringify({scope:'历史规则核查记录，无持久化结构化研判报告',run:legacyRun.value},null,2)],{type:'application/json;charset=utf-8'}));const anchor=document.createElement('a');anchor.href=url;anchor.download=`天亨-历史核查-${legacyRun.value.id}.json`;anchor.click();URL.revokeObjectURL(url)}
watch([()=>props.snapshot?.snapshot_id,()=>props.run?.id],()=>{resolvedRun.value=props.run;recordId.value=props.run?.id||'';void load()},{immediate:true})
onUnmounted(()=>{generation++;clearTimeout(timer)})
</script>
<template><div class="assessment-report-page"><header class="module-header"><div><span class="eyebrow">TIANHENG · RISK ASSESSMENT</span><h2>风险研判与报告</h2><p>同一事件、同一证据快照，展示可追溯的规则分析。</p></div><button class="outline-button" @click="emit('return-workbench')"><Icon name="spark" :size="15"/>返回核查工作台</button></header><label class="device-event-select">查看已保存核查<select v-model="recordId" aria-label="选择风险研判记录" @change="chooseRun"><option value="">请选择已完成的证据核查</option><option v-for="item in savedRuns" :key="item.id" :value="item.id">{{displayText(item.instruction)}} · {{time(item.created_at,true)}}</option></select></label><div v-if="!validRun&&!legacyRun" class="execution-empty"><Icon name="shield" :size="32"/><h3>尚未选择对应的证据核查</h3><p>从地图事件或设备进入核查，或选择已有记录；不会用另一事件的结果填充当前页面。</p><button class="primary-button" @click="emit('return-workbench')">前往证据工作台</button></div><template v-else-if="validRun"><div class="assessment-context"><strong>{{snapshot?.incident.code||report?.incident_code||'核查事件'}} · {{displayText(snapshot?.incident.title||report?.incident.title||validRun.instruction)}}</strong><span>{{label(validRun.status)}} · 规则分析，非大模型推理</span><code>{{validRun.id}}</code><code v-if="snapshot">{{snapshot.snapshot_id}}</code><code v-else>{{validRun.incident_id}}</code></div><p v-if="loading" class="panel-hint" role="status">正在读取持久化研判报告…</p><div v-if="error" class="evidence-error" role="alert">{{displayText(error)}}<p>早期记录可能没有结构化报告，可返回同一证据快照重新执行核查。原记录保持不变。</p><button class="text-button" @click="load">重新读取报告</button></div><p v-if="!loading&&!error&&!report" class="panel-hint">核查尚未完成，结构化报告将在成功完成后保存。</p></template><article v-if="legacyRun?.result" class="assessment-saved-report"><div class="execution-section-heading"><h3>{{displayText(legacyRun.result.title)}}</h3><span class="risk-pill" :class="legacyRun.result.level">{{label(legacyRun.result.level)}}</span></div><p class="execution-scope">历史基础核查 · {{ruleVersionText(legacyRun.result.rule_version)}} · 此记录没有结构化报告；保留原始结果，可从地图事件重新建立证据核查。</p><code>{{legacyRun.id}} · {{legacyRun.incident_id}}</code><h4>保存时的规则分析</h4><ul><li v-for="item in legacyRun.result.reasons" :key="item">{{displayText(item)}}</li></ul><h4>证据依据</h4><div v-for="item in legacyRun.result.evidence" :key="item.source_id" class="assessment-regional"><strong>{{displayText(item.label)}} · {{displayText(item.value)}}</strong><code>{{item.source_id}}</code></div><h4>不确定性</h4><ul><li v-for="item in legacyRun.result.uncertainties" :key="item">{{displayText(item)}}</li></ul><h4>核查建议</h4><ul><li v-for="item in legacyRun.result.recommendations" :key="item">{{displayText(item)}}</li></ul><button class="outline-button" @click="downloadLegacy"><Icon name="download" :size="15"/>保存历史核查记录 JSON</button></article><template v-if="report"><article class="assessment-saved-report"><div class="execution-section-heading"><h3>{{displayText(report.title)}}</h3><span class="risk-pill" :class="report.assessment.level">{{label(report.assessment.level)}}</span></div><p class="execution-scope">规则研判 · {{ruleVersionText(report.rule_version)}} · {{time(report.created_at,true)}} 保存。温度异常不等于已确认火灾。</p><dl class="execution-facts"><div><dt>事件</dt><dd>{{report.incident_code||report.incident_id}}</dd></div><div><dt>目标位置</dt><dd>{{displayText(report.incident.building_name||report.incident.location_name)}}</dd></div><div><dt>证据采样数</dt><dd>{{report.observations.length}} 条 · {{report.devices.length}} 台关联设备</dd></div><div><dt>保存的事件状态</dt><dd>{{label(report.incident.status)}}</dd></div></dl><h4>风险判断</h4><p>{{displayText(report.assessment.risk_judgment||report.assessment.title)}}</p><ul><li v-for="item in report.assessment.reasons" :key="item">{{displayText(item)}}</li></ul><h4>温度趋势</h4><div v-for="trend in report.assessment.temperature_trends||[]" :key="trend.device_id" class="assessment-trend"><strong>{{trend.device_code}} · {{trend.sample_count}} 个采样点</strong><p>{{trend.first_value??'—'}}℃ → {{trend.latest_value??'—'}}℃ · 变化 {{trend.delta??'—'}}℃ · {{trend.duration_minutes??'—'}} 分钟</p><small>{{trend.direction==='insufficient'?'样本不足，不能判断趋势':trend.direction==='rising'?'采样区间上升':trend.direction==='falling'?'采样区间下降':'采样区间稳定'}}{{trend.slope_per_minute===null?'':` · ${trend.slope_per_minute}℃/分钟`}}</small><details><summary>样本时间和来源</summary><p>{{time(trend.started_at,true)}} — {{time(trend.ended_at,true)}}</p><code v-for="id in trend.observation_ids" :key="id">{{id}}</code></details></div><p v-if="!report.assessment.temperature_trends?.length" class="panel-hint">本事件没有可分析的温度趋势。</p><h4>关联区域证据</h4><div v-for="item in report.assessment.regional_evidence||[]" :key="item.observation_id" class="assessment-regional"><strong>{{item.device_code}} · {{item.kind}} · {{item.value??'未知'}} {{item.unit}}</strong><p>{{displayText(item.interpretation)}}</p><small>{{time(item.observed_at,true)}} · {{label(item.quality)}} · 事件快照</small><code>{{item.observation_id}}</code></div><p v-if="!report.assessment.regional_evidence?.length" class="panel-hint">没有额外区域证据，不能据此认定现场正常。</p><h4>可能原因</h4><ul><li v-for="item in report.assessment.possible_causes||[]" :key="item">{{displayText(item)}}</li></ul><h4>处置建议</h4><ul><li v-for="item in report.assessment.recommendations" :key="item">{{displayText(item)}}</li></ul><h4>信息缺口与不确定性</h4><ul><li v-for="item in report.assessment.uncertainties" :key="item">{{displayText(item)}}</li></ul><h4>本次规则参考</h4><div v-for="reference in report.references" :key="reference.rule_id" class="assessment-reference"><strong>{{displayText(reference.reference_label)}}</strong><p>{{displayText(reference.source_label)}} · {{ruleVersionText(reference.rule_version)}}</p></div><h4>适用范围</h4><ul><li v-for="item in report.limitations" :key="item">{{displayText(item)}}</li></ul><code>{{report.id}}</code><div class="execution-action-row"><button class="primary-button" @click="download"><Icon name="download" :size="15"/>保存规则研判报告 JSON</button><button class="outline-button" @click="emit('return-workbench')">返回核查并规划执行任务</button></div></article><section class="execution-followup"><h3>关联执行任务与反馈</h3><button v-for="task in linked" :key="task.id" class="execution-linked-task" @click="emit('open-task',task.id)"><span>{{task.code}} · {{displayText(task.title)}}<small>{{task.report?'执行报告已保存，待人工复核':task.resource_code||'资源待分配'}}</small></span><span class="execution-status" :class="task.status">{{executionStatuses[task.status]}}</span><b>{{Math.round(task.progress)}}%</b></button><p v-if="!linked.length" class="execution-muted">此核查尚未关联执行任务。可返回工作台创建，原事件不会被自动关闭。</p></section></template></div></template>
